import React, { useEffect, useState } from 'react';
import { Card, CardHeader, KPICard, Spinner, AlertBanner } from '../components/ui/Card';
import api from '../utils/api';

export default function DashboardPage() {
  const [data, setData]     = useState(null);
  const [bcc,  setBcc]      = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    document.getElementById('page-title') && (document.getElementById('page-title').textContent = 'Tableau de bord');
    Promise.all([
      api.get('/dashboard'),
      api.get('/bcc/stats').catch(() => null),
    ]).then(([d, b]) => {
      setData(d.data);
      if (b) setBcc(b.data.data);
    }).finally(() => setLoading(false));
  }, []);

  if (loading) return <Spinner />;
  if (!data)   return <AlertBanner type="error" message="Impossible de charger le tableau de bord" />;

  const { stats, alerts = [], recentActivity = [] } = data;

  return (
    <div className="animate-fade">
      {/* KPIs */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit,minmax(200px,1fr))', gap: 14, marginBottom: 20 }}>
        <KPICard icon="👥" label="Personnel actif"   value={stats.totalPersonnel}   color="var(--navy)" />
        <KPICard icon="🤝" label="Volontaires"        value={stats.totalVolunteers}  color="#7c3aed" />
        <KPICard icon="🎯" label="Projets actifs"     value={stats.activeProjects}   color="#0891b2" />
        <KPICard icon="📦" label="Stock critique"     value={stats.criticalStock}    color={stats.criticalStock > 0 ? 'var(--red)' : 'var(--emerald)'} />
        <KPICard icon="📅" label="Congés en attente"  value={stats.pendingLeave}     color={stats.pendingLeave > 0 ? 'var(--orange)' : 'var(--emerald)'} />
        {bcc && <KPICard icon="📖" label="Étudiants BCC" value={bcc.total} color="#c9a84c" />}
      </div>

      {/* Alertes */}
      {alerts.length > 0 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 8, marginBottom: 20 }}>
          {alerts.map((a, i) => (
            <AlertBanner key={i} type={a.severity === 'high' ? 'error' : 'warning'} message={a.message} />
          ))}
        </div>
      )}

      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 16 }}>
        {/* Activité récente */}
        <Card>
          <CardHeader title="Activité récente" subtitle="Dernières actions enregistrées" />
          {recentActivity.length === 0 ? (
            <p style={{ color: 'var(--gray-400)', fontStyle: 'italic', fontSize: '0.88rem' }}>Aucune activité récente</p>
          ) : (
            <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
              {recentActivity.slice(0, 8).map((log, i) => (
                <div key={i} style={{ display: 'flex', gap: 12, padding: '8px 0', borderBottom: '1px solid var(--gray-100)' }}>
                  <div style={{ width: 32, height: 32, borderRadius: '50%', background: 'var(--gray-100)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '0.75rem', fontWeight: 700, color: 'var(--navy)', flexShrink: 0 }}>
                    {(log.user_name || log.username || '?')[0].toUpperCase()}
                  </div>
                  <div style={{ flex: 1 }}>
                    <p style={{ fontSize: '0.82rem', color: 'var(--navy)', fontWeight: 500 }}>
                      <span style={{ fontWeight: 700 }}>{log.user_name || log.username}</span> — {log.action}
                      {log.object && <span style={{ color: 'var(--gray-400)' }}> sur {log.object}</span>}
                    </p>
                    {log.new_value && <p style={{ fontSize: '0.72rem', color: 'var(--gray-400)', marginTop: 2 }}>{log.new_value}</p>}
                    <p style={{ fontSize: '0.7rem', color: 'var(--gray-400)', marginTop: 2 }}>
                      {log.timestamp ? new Date(log.timestamp).toLocaleString('fr-FR') : ''}
                    </p>
                  </div>
                </div>
              ))}
            </div>
          )}
        </Card>

        {/* BCC Stats */}
        {bcc && (
          <Card>
            <CardHeader title="BCC — Aperçu" subtitle="Bible Correspondence Course" />
            <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
              {[
                { flag: '🇫🇷', label: 'Français',  count: bcc.parLangue.Français  || 0, color: '#0f2044' },
                { flag: '🇬🇧', label: 'English',   count: bcc.parLangue.English   || 0, color: '#0891b2' },
                { flag: '🇲🇬', label: 'Malagasy',  count: bcc.parLangue.Malagasy  || 0, color: '#7c3aed' },
              ].map(l => (
                <div key={l.label} style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
                  <span style={{ fontSize: '1.2rem' }}>{l.flag}</span>
                  <span style={{ flex: 1, fontSize: '0.88rem', fontWeight: 500 }}>{l.label}</span>
                  <span style={{ fontWeight: 700, color: l.color, fontSize: '1.1rem' }}>{l.count}</span>
                </div>
              ))}
              <div style={{ borderTop: '1px solid var(--gray-100)', paddingTop: 10, marginTop: 4 }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.85rem' }}>
                  <span style={{ color: 'var(--gray-500)' }}>Classe 1</span>
                  <span style={{ fontWeight: 700 }}>{bcc.parClasse['1'] || 0}</span>
                </div>
                <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.85rem', marginTop: 4 }}>
                  <span style={{ color: 'var(--gray-500)' }}>Classe 2</span>
                  <span style={{ fontWeight: 700 }}>{bcc.parClasse['2'] || 0}</span>
                </div>
                <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.85rem', marginTop: 4 }}>
                  <span style={{ color: '#16a34a', fontWeight: 600 }}>✅ Terminés</span>
                  <span style={{ fontWeight: 700, color: '#16a34a' }}>{bcc.parStatut.termine || 0}</span>
                </div>
              </div>
            </div>
          </Card>
        )}
      </div>
    </div>
  );
}
